INSERT INTO process_calculator_mappings (process_group, process_route, operation, calculator_id, calculator_name, is_active, display_order, machine_class, canonical_process_id)
SELECT $str$Casting Investment$str$, v.name, v.name, NULL, NULL, false, v.display_order, v.machine_class, pt.id
FROM process_taxonomy pt
JOIN (VALUES
  ($str$Band Saw$str$, 3000, $str$casting_investment_band_saw$str$),
  ($str$Belt Sand$str$, 3001, $str$casting_investment_belt_sand$str$),
  ($str$Bench Operation$str$, 3002, $str$casting_investment_bench_operation$str$),
