  ($str$Ceramic Core Firing$str$, 3004, $str$casting_investment_ceramic_core_firing$str$),
  ($str$Ceramic Core Making$str$, 3005, $str$casting_investment_ceramic_core_making$str$),
  ($str$Ceramic Leaching$str$, 3006, $str$casting_investment_ceramic_leaching$str$),
  ($str$Chemical Etching$str$, 3007, $str$casting_investment_chemical_etching$str$),
  ($str$Cooling$str$, 3008, $str$casting_investment_cooling$str$),
  ($str$Drying$str$, 3009, $str$casting_investment_drying$str$),
  ($str$Flash Fire De-Waxing$str$, 3010, $str$casting_investment_flash_fire_de_waxing$str$),
  ($str$Knockout$str$, 3011, $str$casting_investment_knockout$str$),
  ($str$Metal Pouring$str$, 3012, $str$casting_investment_metal_pouring$str$),
  ($str$Mold Burnout$str$, 3013, $str$casting_investment_mold_burnout$str$),
  ($str$Mold Preheating$str$, 3014, $str$casting_investment_mold_preheating$str$),
  ($str$Primary Sand Coating$str$, 3015, $str$casting_investment_primary_sand_coating$str$),
  ($str$Primary Slurry Dipping$str$, 3016, $str$casting_investment_primary_slurry_dipping$str$),
  ($str$Robotic Assist$str$, 3017, $str$casting_investment_robotic_assist$str$),
  ($str$Secondary Sand Coating$str$, 3018, $str$casting_investment_secondary_sand_coating$str$),
  ($str$Secondary Slurry Dipping$str$, 3019, $str$casting_investment_secondary_slurry_dipping$str$),
  ($str$Soluble Wax Core Making$str$, 3020, $str$casting_investment_soluble_wax_core_making$str$),
  ($str$Soluble Wax Leaching$str$, 3021, $str$casting_investment_soluble_wax_leaching$str$),
