INSERT INTO process_calculator_mappings (process_group, process_route, operation, calculator_id, calculator_name, is_active, display_order, machine_class, canonical_process_id)
SELECT $str$Assembly Plastic Molding$str$, v.name, v.name, NULL, NULL, false, v.display_order, v.machine_class, pt.id
FROM process_taxonomy pt
JOIN (VALUES
  ($str$Multi-Shot Molding$str$, 3200, $str$assembly_plastic_molding_multi_shot_molding$str$),
  ($str$Pick and Place$str$, 3201, $str$assembly_plastic_molding_pick_and_place$str$)
) AS v(name, display_order, machine_class)
  ON pt.process_group = $str$Assembly Plastic Molding$str$ AND pt.process_name = v.name
WHERE NOT EXISTS (
  SELECT 1 FROM process_calculator_mappings m WHERE m.process_group = $str$Assembly Plastic Molding$str$ AND m.operation = v.name
)
ON CONFLICT (process_group, process_route, operation) DO NOTHING;

